/**
 * kon-cardsim
 *
 * Creador de simuladores de cartas: juegos por datos, salas, matches, replay y clasificación
 */
export interface CardsimApi {
  /**
   * Delete a deck
   *
   * Deletes a deck. Owner or admin. Cannot be undone.
   *
   * REST: `DELETE /api/cardsim/decks/{id}` · scope `kon:cardsim:borrar-mazo`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `cardsim__borrar-mazo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarMazo: Operation<BorrarMazoParams, BorrarMazoResponse>;
  /**
   * Search a game's card catalogue
   *
   * Deck-builder search: `q` filters by name (contains, case-insensitive); any OTHER query key is a facet over the card data (`?type=Pal&color=Red`, exact match, arrays match any value). Paged with `page` and `pageSize` (max 200, default 60). Public.
   *
   * REST: `GET /api/cardsim/games/{slug}/cards` · scope `kon:cardsim:buscar-cartas`
   * idempotent (safe to retry) · MCP tool `cardsim__buscar-cartas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly buscarCartas: PageableOperation<BuscarCartasParams, BuscarCartasResponse, BuscarCartasItem>;
  /**
   * Find a room by its code
   *
   * Short room code → session id, game, status, whether it has a password and allows spectators. Knowing the code grants nothing by itself. Public.
   *
   * REST: `GET /api/cardsim/rooms/{code}` · scope `kon:cardsim:buscar-sala-por-codigo`
   * idempotent (safe to retry) · MCP tool `cardsim__buscar-sala-por-codigo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly buscarSalaPorCodigo: Operation<BuscarSalaPorCodigoParams, BuscarSalaPorCodigoResponse>;
  /**
   * Cancel the pending undo request
   *
   * Clears the room's pending undo request. Seated players only.
   *
   * REST: `DELETE /api/cardsim/sessions/{id}/undo` · scope `kon:cardsim:cancelar-deshacer`
   * idempotent (safe to retry) · MCP tool `cardsim__cancelar-deshacer`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly cancelarDeshacer: Operation<CancelarDeshacerParams, CancelarDeshacerResponse>;
  /**
   * Save a deck
   *
   * Saves a deck for a game: `cards` is a flat list of cardIds or a map section → cardIds. It is validated against the game's rules when SAVING (422 with `issues`). The deck is private; it gets a share code. A person with a session, or an agent with cardsim:create.
   *
   * REST: `POST /api/cardsim/decks` · scope `kon:cardsim:crear-mazo`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__crear-mazo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearMazo: Operation<CrearMazoParams, CrearMazoResponse>;
  /**
   * Create a room (a game session)
   *
   * Opens a room for a game with your deck(s) (`deckIds`, yours). Open seats wait for players (sentarse-en-sala); `solo: true` seats you everywhere. Optional password, spectators, best-of match and chess clock. The shuffle seed is the server's; `seed` is only accepted in solo (422 otherwise). A person with a session, or an agent with cardsim:create.
   *
   * REST: `POST /api/cardsim/sessions` · scope `kon:cardsim:crear-sala`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__crear-sala`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearSala: Operation<CrearSalaParams, CrearSalaResponse>;
  /**
   * Rewrite a deck
   *
   * Replaces a deck's name and cards, validated again against the game's rules (422 with `issues`). The game cannot change. Owner or admin; 409 if the game no longer exists.
   *
   * REST: `PUT /api/cardsim/decks/{id}` · scope `kon:cardsim:editar-mazo`
   * idempotent (safe to retry) · MCP tool `cardsim__editar-mazo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarMazo: Operation<EditarMazoParams, EditarMazoResponse>;
  /**
   * Join the matchmaking queue
   *
   * Queues you for a game with one of your decks. If someone else is already waiting for the same game (and rated flag), a best-of-1 game starts at once (201 with the session and your seat); otherwise you wait (202, the other player is notified when matched). A person with a session, or an agent with cardsim:create.
   *
   * REST: `POST /api/cardsim/queue` · scope `kon:cardsim:entrar-en-cola`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__entrar-en-cola`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly entrarEnCola: Operation<EntrarEnColaParams, EntrarEnColaResponse>;
  /**
   * Play an action at the table
   *
   * Applies one action from YOUR seat (`seat` must be yours; the action's player is forced to it). Illegal actions, actions that would reveal an opponent's hidden cards and late actions (clock out) are a 409 and never enter the log. Returns your new view, the action count, the result and the clocks.
   *
   * REST: `POST /api/cardsim/sessions/{id}/action` · scope `kon:cardsim:enviar-accion`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__enviar-accion`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly enviarAccion: Operation<EnviarAccionParams, EnviarAccionResponse>;
  /**
   * Export a deck as text
   *
   * The deck as a plain-text list (`format=ydk` for a YDK file). Same visibility as ver-mazo: owner, or the share code in `share`.
   *
   * REST: `GET /api/cardsim/decks/{id}/export` · scope `kon:cardsim:exportar-mazo`
   * idempotent (safe to retry) · MCP tool `cardsim__exportar-mazo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly exportarMazo: Operation<ExportarMazoParams, ExportarMazoResponse>;
  /**
   * Open a sealed pool
   *
   * Opens N packs (`packs`, default 6, max 24) of M cards (`packSize`, default 7) from the game's catalogue, optionally only from some `sets` and with a per-rarity pack layout (`slots`, e.g. {"R":1,"U":3,"C":3}; at most 30 cards). Returns the server seed so the same pool can be rebuilt. Saves nothing. Any account.
   *
   * REST: `POST /api/cardsim/games/{slug}/sealed` · scope `kon:cardsim:generar-sellado`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__generar-sellado`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly generarSellado: Operation<GenerarSelladoParams, GenerarSelladoResponse>;
  /**
   * Bulk import cards into a game's catalogue
   *
   * Upserts cards by `(game, cardId)`: re-importing a corrected catalogue updates, it does not duplicate. Repeated cardIds in the batch collapse (last wins); rows without cardId or name are skipped. Returns created/updated/total/collapsed/skipped. At most 20,000 cards per call (413). Editorial: admin/editor, or an agent with cardsim:manageCatalog.
   *
   * REST: `POST /api/cardsim/games/{slug}/cards` · scope `kon:cardsim:importar-cartas`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `cardsim__importar-cartas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_PAYLOAD_TOO_LARGE`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly importarCartas: Operation<ImportarCartasParams, ImportarCartasResponse>;
  /**
   * Import a deck list
   *
   * Parses a pasted deck list (`format: text`, e.g. `4 BP01-001` or `4 Card Name`, or `ydk`), resolves cards by id or by name, validates it and saves it only if clean (201). Otherwise 422 with the parsed deck, the lines that did not parse, the unknown cards and the rule issues. A person with a session, or an agent with cardsim:create.
   *
   * REST: `POST /api/cardsim/decks/import` · scope `kon:cardsim:importar-mazo`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__importar-mazo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly importarMazo: Operation<ImportarMazoParams, ImportarMazoResponse>;
  /**
   * List published games
   *
   * Every published card game (slug, name, full definition), by name. Use the slug with ver-juego, buscar-cartas or ver-clasificacion. Public.
   *
   * REST: `GET /api/cardsim/games` · scope `kon:cardsim:listar-juegos`
   * idempotent (safe to retry) · MCP tool `cardsim__listar-juegos`
   * Errors: `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarJuegos: Operation<void, ListarJuegosResponse>;
  /**
   * List my decks
   *
   * The caller's saved decks, most recently updated first, optionally for one `gameId`. Any account.
   *
   * REST: `GET /api/cardsim/decks` · scope `kon:cardsim:listar-mis-mazos`
   * idempotent (safe to retry) · MCP tool `cardsim__listar-mis-mazos`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarMisMazos: Operation<ListarMisMazosParams, ListarMisMazosResponse>;
  /**
   * List the built-in game presets
   *
   * The game definitions shipped with the kon (id, name, players, zone count, deck sections with their size range). Publish one with publicar-juego `{ slug, preset }`. Public.
   *
   * REST: `GET /api/cardsim/presets` · scope `kon:cardsim:listar-presets`
   * idempotent (safe to retry) · MCP tool `cardsim__listar-presets`
   * Errors: `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarPresets: Operation<void, ListarPresetsResponse>;
  /**
   * List open public rooms
   *
   * The lobby: open public rooms (latest 50), optionally of one `gameId`. Only what is needed to decide to join (seats taken, password or not, spectators) — never decks or the action log. Public.
   *
   * REST: `GET /api/cardsim/sessions` · scope `kon:cardsim:listar-salas`
   * idempotent (safe to retry) · MCP tool `cardsim__listar-salas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarSalas: Operation<ListarSalasParams, ListarSalasResponse>;
  /**
   * Ask to undo back to an action count
   *
   * Truncates the game back to `toActionCount` actions. Solo games undo at once; with an opponent it is a request (`pending: true`) that applies when the other seat asks for the same count. Seated players only; not on finished games (409).
   *
   * REST: `POST /api/cardsim/sessions/{id}/undo` · scope `kon:cardsim:pedir-deshacer`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__pedir-deshacer`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly pedirDeshacer: Operation<PedirDeshacerParams, PedirDeshacerResponse>;
  /**
   * Start a rematch
   *
   * Same table, same decks and seats, new seed. In an undecided match it counts as the next game; after a decided match it is a friendly game. Seated players of a finished game only (409 if not finished).
   *
   * REST: `POST /api/cardsim/sessions/{id}/rematch` · scope `kon:cardsim:pedir-revancha`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__pedir-revancha`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly pedirRevancha: Operation<PedirRevanchaParams, PedirRevanchaResponse>;
  /**
   * Publish or rewrite a game definition
   *
   * Publishes a game by `slug` from a full `definition`, or from a built-in `preset` id (see listar-presets; then the slug defaults to the preset id). The definition is validated first (422 with `issues`). Rewrites the game if the slug exists (200), creates it otherwise (201). Editorial: admin/editor, or an agent with cardsim:manageCatalog.
   *
   * REST: `PUT /api/cardsim/games` · scope `kon:cardsim:publicar-juego`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `cardsim__publicar-juego`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly publicarJuego: Operation<PublicarJuegoParams, PublicarJuegoResponse>;
  /**
   * Leave the matchmaking queue
   *
   * Removes you from every queue. Any account.
   *
   * REST: `DELETE /api/cardsim/queue` · scope `kon:cardsim:salir-de-la-cola`
   * idempotent (safe to retry) · MCP tool `cardsim__salir-de-la-cola`
   * Errors: `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly salirDeLaCola: Operation<void, SalirDeLaColaResponse>;
  /**
   * Take a seat in a room
   *
   * Sits you in an open seat with one of your decks (of the room's game), with the room password if it has one (403 if wrong; rate-limited). The game starts when every seat is taken. 409 if the room is no longer open, the seat is taken or you are already seated.
   *
   * REST: `POST /api/cardsim/sessions/{id}/join` · scope `kon:cardsim:sentarse-en-sala`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__sentarse-en-sala`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly sentarseEnSala: Operation<SentarseEnSalaParams, SentarseEnSalaResponse>;
  /**
   * Goldfish a deck (opening-hand statistics)
   *
   * Shuffles a deck many times (`iterations`, default 10,000, max 50,000) and answers `queries` such as "at least 2 lands by turn 3". Takes a saved deck (`deckId`; yours, or with its code in `share`) or a loose one (`gameId` + `cards`). Returns the seed, so the same report (and the same hands for another deck) can be reproduced. Saves nothing. Public for loose decks.
   *
   * REST: `POST /api/cardsim/goldfish` · scope `kon:cardsim:simular-goldfish`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `cardsim__simular-goldfish`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly simularGoldfish: Operation<SimularGoldfishParams, SimularGoldfishResponse>;
  /**
   * Sync a game's catalogue from a CMS dataset
   *
   * Upserts the game's cards from a dataset (`datasetId`, or the one the game already has pinned). `idField` picks the entry field used as cardId and is pinned with the game, so later syncs cannot silently switch it. 404 if the dataset does not exist or you cannot read it (same answer on purpose); 422 if it produced no card. Editorial: admin/editor, or an agent with cardsim:manageCatalog.
   *
   * REST: `POST /api/cardsim/games/{slug}/sync-catalog` · scope `kon:cardsim:sincronizar-catalogo`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `cardsim__sincronizar-catalogo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly sincronizarCatalogo: Operation<SincronizarCatalogoParams, SincronizarCatalogoResponse>;
  /**
   * Get a game's Elo leaderboard
   *
   * Top 100 ratings of a game (rating, wins, losses, draws per user). Public.
   *
   * REST: `GET /api/cardsim/ratings/{slug}` · scope `kon:cardsim:ver-clasificacion`
   * idempotent (safe to retry) · MCP tool `cardsim__ver-clasificacion`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verClasificacion: Operation<VerClasificacionParams, VerClasificacionResponse>;
  /**
   * Get a game by slug
   *
   * A published game: its definition, how many cards its catalogue has (`cardCount`) and its deck sections. 404 if the slug does not exist. Public.
   *
   * REST: `GET /api/cardsim/games/{slug}` · scope `kon:cardsim:ver-juego`
   * idempotent (safe to retry) · MCP tool `cardsim__ver-juego`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verJuego: Operation<VerJuegoParams, VerJuegoResponse>;
  /**
   * Get a match (best-of series)
   *
   * A match with its wins per seat and the games played (id, index, status, result). Public.
   *
   * REST: `GET /api/cardsim/matches/{id}` · scope `kon:cardsim:ver-match`
   * idempotent (safe to retry) · MCP tool `cardsim__ver-match`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verMatch: Operation<VerMatchParams, VerMatchResponse>;
  /**
   * Get a deck
   *
   * A deck by id. Decks are private: only the owner sees it, or whoever brings its share code in `share`. Someone else's deck without the code is a 404.
   *
   * REST: `GET /api/cardsim/decks/{id}` · scope `kon:cardsim:ver-mazo`
   * idempotent (safe to retry) · MCP tool `cardsim__ver-mazo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verMazo: Operation<VerMazoParams, VerMazoResponse>;
  /**
   * Get the table as you may see it
   *
   * The game state FOR the caller: a seated player gets their seat's view (own hand visible, opponents' hands as counts, deck order never), anyone else the spectator view with no secrets (403 if the room has no spectators). Also the definition, action count, pending undo, clocks; reading also enforces the clock (`timedOut`).
   *
   * REST: `GET /api/cardsim/sessions/{id}` · scope `kon:cardsim:ver-partida`
   * idempotent (safe to retry) · MCP tool `cardsim__ver-partida`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verPartida: Operation<VerPartidaParams, VerPartidaResponse>;
  /**
   * Get the full replay of a finished game
   *
   * Definition, every deck, seed, the random sub-seeds used and the whole action log, to replay the game. Only once the game is finished (409 before); a room without spectators only shows it to its players (403).
   *
   * REST: `GET /api/cardsim/sessions/{id}/replay` · scope `kon:cardsim:ver-replay`
   * idempotent (safe to retry) · MCP tool `cardsim__ver-replay`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verReplay: Operation<VerReplayParams, VerReplayResponse>;
}
